"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import {
  creamBevel,
  creamBevelHover,
  focusRing,
  pressScale,
  quietBevel,
  raisedBevel,
} from "./_shared";

/**
 * Burnished IconButton: a single glyph on the same bevels as the Button.
 *
 * Round by default, like every Burnished pill; the square shape keeps a
 * corner that grows with the button. The default is the graphite bevel,
 * `primary` is the cream face, and ghost is the quiet choice for toolbars.
 * A press scales it a little toward the page.
 */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    pressScale,
    focusRing,
    "disabled:pointer-events-none disabled:opacity-50",
    "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: raisedBevel,
        primary: cn(creamBevel, creamBevelHover),
        secondary: quietBevel,
        ghost:
          "bg-transparent text-muted-foreground [@media(hover:hover)_and_(pointer:fine)]:hover:bg-accent [@media(hover:hover)_and_(pointer:fine)]:hover:text-foreground",
        destructive:
          "bg-(image:--fill-destructive) text-destructive-foreground shadow-(--bevel-primary)",
        outline: raisedBevel,
      },
      size: {
        xs: "size-7 rounded-md [&_svg]:size-3.5",
        sm: "size-9 rounded-md [&_svg]:size-4",
        default: "size-11 rounded-lg [&_svg]:size-4",
        lg: "size-12 rounded-lg [&_svg]:size-5",
        xl: "size-14 rounded-xl [&_svg]:size-5",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "circle",
    },
  },
);

/** Props for the IconButton. Give it an `aria-label`, since the glyph carries no text. */
export interface IconButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
